#!/usr/bin/env python3
"""Rebuild the self-contained accessible local viewer from catalogue.json."""
from pathlib import Path
import json,html
D=Path(__file__).resolve().parents[1];c=json.loads((D/'catalogue.json').read_text());data=[];h=html.escape
for m in sorted(c['meanings'],key=lambda m:m['label']):
 data.append({**{k:m[k] for k in ['label','parent_concept_id','adaptation_note','profiles','source_acceptance_requirement']},'frames':[{k:f[k] for k in ['frame_number','title','teaching_key','master_path','exports']} for f in sorted(c['frames'],key=lambda f:f['frame_number']) if f['parent_concept_id']==m['parent_concept_id']]})
buttons=''.join(f'<li data-search="{h((m["label"]+" "+m["parent_concept_id"]).lower(),quote=True)}"><button type="button" data-open="{i}">{h(m["label"])}</button><span> {len(m["frames"])} frames</span></li>' for i,m in enumerate(data))
fallback=''.join('<details><summary>'+h(m['label'])+'</summary><p>'+h(m['adaptation_note'])+'</p>'+''.join('<h3>'+h(str(f['frame_number'])+'. '+f['title'])+'</h3><p>'+h(f['teaching_key'])+'</p><ul>'+''.join('<li><a href="'+h(e['source_path'],quote=True)+'">'+h(e['profile'])+' SVG</a></li>' for e in f['exports'])+'</ul>' for f in m['frames'])+'</details>' for m in data)
payload=json.dumps(data,separators=(',',':')).replace('<','\\u003c').replace('&','\\u0026')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tactile display adaptations — 42 meanings</title>
<style>body{font:1.1rem/1.55 system-ui,sans-serif;color:#17283a;background:#f8fafc;margin:0}main{max-width:72rem;margin:auto;padding:1.2rem}a{color:#084fa3}button,input,select{font:inherit;padding:.6rem;border:2px solid #526477;border-radius:.25rem;background:white;color:#17283a}button{cursor:pointer}button:hover{background:#edf4ff}button:disabled{color:#63707b;cursor:default} :focus-visible{outline:3px solid #a83a00;outline-offset:3px}li{margin:.5rem 0}ul{padding-left:1.5rem}#list{list-style:none;padding:0}#list button{text-align:left}#list span{color:#46576a}.controls{display:flex;gap:.65rem;flex-wrap:wrap;align-items:center}.field{display:flex;flex-direction:column;gap:.25rem;margin:.5rem 0}dialog{width:min(76rem,94vw);max-height:92vh;box-sizing:border-box;padding:1.2rem;border:2px solid #526477;border-radius:.5rem;overflow:auto}dialog::backdrop{background:#0009}dialog h2{margin:.4rem 0}#art{display:block;width:100%;max-height:52vh;object-fit:contain;background:white;image-rendering:pixelated;margin:1rem auto}#key{white-space:pre-wrap}#frameSelect{max-width:100%}.note{border-left:4px solid #526477;padding-left:1rem}.skip{position:absolute;left:-10000px}.skip:focus{left:1rem;top:1rem;background:white;padding:1rem;z-index:10}[hidden]{display:none!important}details{margin:1rem 0}summary{cursor:pointer}</style></head>
<body><a class="skip" href="#list">Skip to symbols</a><main><h1>Tactile display adaptations</h1><p><strong>42 meanings · 281 teaching frames · 546 SVGs.</strong> Separate native-grid adaptations for Monarch and Dot Pad. The originals and page-fit collection remain unchanged.</p><p class="note">Digitally inspected experimental materials. Actual-device, touch and learner testing are pending. Read each frame’s teaching key; these sequences and layers are not simply smaller original pictures.</p><p><a href="README.md">Overview and reproduction instructions</a> · <a href="KNOWN-LIMITATIONS.md">Known limitations</a> · <a href="catalogue.json">Catalogue</a></p><div id="interactive"><label class="field">Find a symbol<input id="search" type="search" autocomplete="off"></label><p id="resultCount" role="status" aria-live="polite">42 symbols</p><ul id="list">BUTTONS</ul></div><details><summary>All frame links and teaching keys (also works without JavaScript)</summary>FALLBACK</details>
<dialog id="viewer" aria-labelledby="meaningTitle"><div class="controls"><button id="close" type="button" autofocus>Close viewer</button><button id="prevMeaning" type="button">Previous symbol</button><button id="nextMeaning" type="button">Next symbol</button></div><h2 id="meaningTitle"></h2><p id="adaptation"></p><details><summary>Meaning and acceptance requirement</summary><p id="acceptance"></p></details><div class="controls"><label class="field">Display<select id="profile"><option value="monarch-display-v1">Monarch — 96 × 40</option><option value="dotpad-display-v1">Dot Pad — 60 × 40</option></select></label><label class="field">Frame<select id="frameSelect"></select></label></div><div class="controls"><button id="previous" type="button">Previous frame</button><button id="next" type="button">Next frame</button><span id="position" role="status" aria-live="polite"></span></div><h3 id="frameTitle"></h3><img id="art" alt=""><h3>Teaching key</h3><p id="key"></p><p><a id="download" download>Download this SVG</a> · <a id="master" download>Editable frame master</a></p><p>Physical evaluation pending. Escape closes this viewer. All controls work with Tab, Shift+Tab, Enter/Space and the usual select-menu keys.</p></dialog></main>
<script id="data" type="application/json">PAYLOAD</script><script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent),by=id=>document.getElementById(id);let mi=0,fi=0,opener=null;const dlg=by('viewer');
function draw(){const m=data[mi],f=m.frames[fi],p=by('profile').value,e=f.exports.find(x=>x.profile===p);by('frameSelect').value=String(fi);by('frameTitle').textContent=f.title;by('key').textContent=f.teaching_key;by('art').src=e.source_path;by('art').alt=m.label+' — '+f.title+' — '+(p.startsWith('monarch')?'Monarch':'Dot Pad')+' pin-grid graphic; interpretation follows in Teaching key.';by('download').href=e.source_path;by('master').href=f.master_path;by('position').textContent='Frame '+(fi+1)+' of '+m.frames.length+'; symbol '+(mi+1)+' of '+data.length;by('previous').disabled=fi===0;by('next').disabled=fi===m.frames.length-1;by('prevMeaning').disabled=mi===0;by('nextMeaning').disabled=mi===data.length-1;}
function setMeaning(i){mi=i;fi=0;const m=data[mi];by('meaningTitle').textContent=m.label;by('adaptation').textContent=m.adaptation_note;by('acceptance').textContent=m.source_acceptance_requirement;for(const o of by('profile').options)o.disabled=!m.profiles.includes(o.value);if(!m.profiles.includes(by('profile').value))by('profile').value=m.profiles[0];by('frameSelect').replaceChildren(...m.frames.map((f,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+'. '+f.title;return o}));draw();}
by('list').addEventListener('click',ev=>{const b=ev.target.closest('button[data-open]');if(!b)return;opener=b;setMeaning(Number(b.dataset.open));dlg.showModal();by('close').focus();});by('close').addEventListener('click',()=>dlg.close());dlg.addEventListener('close',()=>{if(opener)opener.focus()});by('previous').addEventListener('click',()=>{if(fi>0){fi--;draw()}});by('next').addEventListener('click',()=>{if(fi<data[mi].frames.length-1){fi++;draw()}});by('prevMeaning').addEventListener('click',()=>{if(mi>0)setMeaning(mi-1)});by('nextMeaning').addEventListener('click',()=>{if(mi<data.length-1)setMeaning(mi+1)});by('profile').addEventListener('change',draw);by('frameSelect').addEventListener('change',()=>{fi=Number(by('frameSelect').value);draw()});by('search').addEventListener('input',()=>{const q=by('search').value.toLowerCase().trim();let n=0;for(const li of by('list').children){li.hidden=!li.dataset.search.includes(q);if(!li.hidden)n++}by('resultCount').textContent=n+' of 42 symbols';});
</script><noscript><style>#interactive{display:none}</style><p>Use the “All frame links and teaching keys” section above; the popup viewer needs JavaScript.</p></noscript></body></html>'''.replace('BUTTONS',buttons).replace('FALLBACK',fallback).replace('PAYLOAD',payload)
(D/'index.html').write_text(page)
print('Built index for',len(data),'meanings')
